package com.example.rokidkeyboardbridge;
public class VoiceCaptureTimingPolicyTest{public static void main(String[]args){for(long pause:new long[]{0,500,1000,1500,1800,2199})if(VoiceCaptureTimingPolicy.stop(18000,pause,true))throw new AssertionError("premature pause "+pause);if(!VoiceCaptureTimingPolicy.stop(18000,2200,true)||!VoiceCaptureTimingPolicy.stop(60000,0,true)||VoiceCaptureTimingPolicy.stop(16000,0,true))throw new AssertionError("duration");if(VoiceCaptureTimingPolicy.stop(5999,0,false)||!VoiceCaptureTimingPolicy.stop(6000,0,false))throw new AssertionError("no speech");if(VoiceCaptureTimingPolicy.bridgeTimeoutMs(16000*2*60,16000)<85000)throw new AssertionError("bridge timeout");System.out.println("PASS hesitation 1.5/1.8 seconds, speech beyond16seconds,60-second bound, no-speech and bridge duration budget");}}